mod solution;

fn main() {
    let cases = [
    (r#"[1,2,3,4,5,null,6]"#, r#"1,5,15"#),
    (r#"[2,3,4]"#, r#"2,7"#),
    (r#"
[2,3,4]
"#, r#"2,7"#),
    (r#"  
[1,2,3,4,5,null,6]
  "#, r#"1,5,15"#),
    ];
    for (case_index, (input, expected)) in cases.iter().enumerate() {
        if solution::solve(input) != *expected {
            eprintln!("PRIVATE CASE {} FAILED", case_index + 1);
            std::process::exit(1);
        }
    }
    println!("PASS tree-level-order");
}
